import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import EditIcon from '@/components/icons/EditIcon';
import { useCallback, useEffect, useState } from 'react';
import LoanTypePopup from '../../LoanTypePopup';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import type { LoanTypeDto } from '@/features/selfServices/types/loanType.types';
import LoanIcon, { LoanIcon2 } from '@/assets/svg/Icon';

const MAX_LABEL = 'المبلغ الأقصى:';
const DURATION_LABEL = 'المدة:';
const RATE_LABEL = 'معدل العائد:';

function iconForCode(code: string) {
    if (code === 'personal') {
        return <LoanIcon />;
    }
    return <LoanIcon2 />;
}

function formatMoney(value: number | string) {
    const n = typeof value === 'string' ? Number(value) : value;
    if (!Number.isFinite(n)) return String(value);
    return `${n.toLocaleString('ar-SA', { maximumFractionDigits: 2 })} ريال`;
}

interface LoanTypesStatisticsProps {
    /** `readonly` = employee-facing: no create/edit, only active types. */
    variant?: 'admin' | 'readonly';
}

export default function LoanTypesStatistics({ variant = 'admin' }: LoanTypesStatisticsProps) {
    const [items, setItems] = useState<LoanTypeDto[]>([]);
    const [loading, setLoading] = useState(true);
    const [showPopup, setShowPopup] = useState(false);
    const [editing, setEditing] = useState<LoanTypeDto | null>(null);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const res = await apiGet({
                endpoint: endpoints.loanType.list,
                queryParams: variant === 'readonly' ? { active_only: 1 } : {},
            });
            setItems((res.data?.data ?? []) as LoanTypeDto[]);
        } catch {
            setItems([]);
        } finally {
            setLoading(false);
        }
    }, [variant]);

    useEffect(() => {
        load();
    }, [load]);

    const openCreate = () => {
        setEditing(null);
        setShowPopup(true);
    };

    const openEdit = (row: LoanTypeDto) => {
        setEditing(row);
        setShowPopup(true);
    };

    const closePopup = (open: boolean) => {
        setShowPopup(open);
        if (!open) {
            setEditing(null);
        }
    };

    return (
        <>
            {variant === 'admin' && (
                <div className="flex items-center justify-end w-full mt-6">
                    <PrimaryButton
                        type="button"
                        onClick={openCreate}
                        className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                    >
                        <AddIcon />
                        <p className="text-xs tracking-normal font-normal leading-[22.49px]">إنشاء نوع قرض</p>
                    </PrimaryButton>
                </div>
            )}
            <div className="flex flex-wrap gap-6 w-full mt-4">
                {loading && (
                    <div className="text-sm text-primery-blue-700 w-full py-4 text-center">جاري التحميل...</div>
                )}
                {!loading && items.length === 0 && (
                    <div className="text-sm text-gray-600 w-full py-4 text-center">لا توجد أنواع قروض مضافة.</div>
                )}
                {!loading &&
                    items.map((loan) => (
                        <div
                            key={loan.id}
                            className="flex-1 rounded-2xl border border-[#B6CDE2] bg-[#F4F8FB] p-6 flex items-center justify-between gap-2 shadow-sm min-w-[260px]"
                        >
                            <div className="text-sm text-gray-700 text-start font-extrabold flex-1 min-w-0">
                                <div className="flex items-center gap-2 flex-wrap">
                                    <div className="font-bold text-xl text-start mt-2 mb-1">{loan.name}</div>
                                    {variant === 'admin' && !loan.is_active && (
                                        <span className="text-xs font-semibold rounded-full bg-amber-100 text-amber-900 px-2 py-0.5">
                                            غير مفعّل
                                        </span>
                                    )}
                                </div>
                                <div>
                                    <span className="font-bold">{MAX_LABEL}</span>{' '}
                                    {formatMoney(loan.max_amount)}
                                </div>
                                <div>
                                    <span className="font-bold">{DURATION_LABEL}</span> حتى {loan.max_duration_months}{' '}
                                    شهر
                                </div>
                                <div>
                                    <span className="font-bold">{RATE_LABEL}</span> {loan.interest_rate}%
                                </div>
                            </div>
                            <div className="flex flex-col items-end gap-2 shrink-0">
                                {iconForCode(loan.code)}
                                {variant === 'admin' && (
                                    <button
                                        type="button"
                                        onClick={() => openEdit(loan)}
                                        className="hover:bg-white-blue-300 rounded-full p-1"
                                        aria-label="تعديل"
                                    >
                                        <EditIcon className="text-primery-blue-400" />
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
            </div>
            {variant === 'admin' && (
                <LoanTypePopup
                    open={showPopup}
                    setShowPopup={closePopup}
                    editingLoanType={editing}
                    onRefresh={load}
                />
            )}
        </>
    );
}
