import { z } from 'zod';

export const AddLoanTypeCreateSchema = z.object({
    code: z.string().min(1, 'رمز النوع مطلوب (أحرف إنجليزية صغيرة، أرقام، - أو _)').regex(/^[a-z0-9_-]+$/, 'الرمز غير صالح'),
    loan_type: z.string().min(1, 'اسم القرض مطلوب.'),
    max_amount: z.string().min(1, 'المبلغ الأقصى مطلوب.'),
    return_amount: z.string().min(1, 'معدل العائد مطلوب.'),
    duration_in_months: z.string().min(1, 'المدة بالشهر مطلوبة.'),
    sort_order: z.string().optional(),
    is_active: z.string().min(1, 'الحالة مطلوبة'),
});

export const AddLoanTypeUpdateSchema = z.object({
    loan_type: z.string().min(1, 'اسم القرض مطلوب.'),
    max_amount: z.string().min(1, 'المبلغ الأقصى مطلوب.'),
    return_amount: z.string().min(1, 'معدل العائد مطلوب.'),
    duration_in_months: z.string().min(1, 'المدة بالشهر مطلوبة.'),
    sort_order: z.string().optional(),
    is_active: z.string().min(1, 'الحالة مطلوبة'),
});

export type AddLoanTypeCreateFormValues = z.infer<typeof AddLoanTypeCreateSchema>;
export type AddLoanTypeUpdateFormValues = z.infer<typeof AddLoanTypeUpdateSchema>;
