import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import TextInputForm from '@/components/forms/TextInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import {
    AddLoanTypeCreateFormValues,
    AddLoanTypeCreateSchema,
    AddLoanTypeUpdateFormValues,
    AddLoanTypeUpdateSchema,
} from '@/features/selfServices/forms/schemas/insurances/add-loan-type-schema';
import type { LoanTypeDto } from '@/features/selfServices/types/loanType.types';

interface Props {
    editingLoanType: LoanTypeDto | null;
    setShowPopup: (value: boolean) => void;
    onRefresh: () => void | Promise<void>;
}

export default function LoanTypeForm({ editingLoanType, setShowPopup, onRefresh }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const isEdit = Boolean(editingLoanType);

    const defaultValues = useMemo((): AddLoanTypeCreateFormValues | AddLoanTypeUpdateFormValues => {
        if (!editingLoanType) {
            return {
                code: '',
                loan_type: '',
                max_amount: '',
                return_amount: '',
                duration_in_months: '',
                sort_order: '0',
                is_active: '1',
            };
        }
        return {
            loan_type: editingLoanType.name,
            max_amount: String(editingLoanType.max_amount),
            return_amount: String(editingLoanType.interest_rate),
            duration_in_months: String(editingLoanType.max_duration_months),
            sort_order: String(editingLoanType.sort_order ?? 0),
            is_active: editingLoanType.is_active ? '1' : '0',
        };
    }, [editingLoanType]);

    const form = useForm<AddLoanTypeCreateFormValues | AddLoanTypeUpdateFormValues>({
        resolver: zodResolver(isEdit ? AddLoanTypeUpdateSchema : AddLoanTypeCreateSchema) as any,
        defaultValues,
    });

    useEffect(() => {
        form.reset(defaultValues);
    }, [defaultValues, form]);

    const parseActive = (raw: string | undefined) => raw !== '0' && raw !== 'false';

    const onSubmit = async (data: AddLoanTypeCreateFormValues | AddLoanTypeUpdateFormValues) => {
        setLoading(true);
        setError(null);
        try {
            if (isEdit && editingLoanType) {
                const u = data as AddLoanTypeUpdateFormValues;
                const body = {
                    name: u.loan_type,
                    max_amount: Number(u.max_amount),
                    max_duration_months: Number(u.duration_in_months),
                    interest_rate: Number(u.return_amount),
                    sort_order: u.sort_order ? Number(u.sort_order) : 0,
                    is_active: parseActive(u.is_active),
                };
                await apiPost({
                    endpoint: endpoints.loanType.update + editingLoanType.id,
                    body,
                });
                toast.success('تم حفظ التعديلات');
            } else {
                const d = data as AddLoanTypeCreateFormValues;
                const body = {
                    code: d.code.trim().toLowerCase(),
                    name: d.loan_type,
                    max_amount: Number(d.max_amount),
                    max_duration_months: Number(d.duration_in_months),
                    interest_rate: Number(d.return_amount),
                    sort_order: d.sort_order ? Number(d.sort_order) : 0,
                    is_active: parseActive(d.is_active),
                };
                await apiPost({
                    endpoint: endpoints.loanType.create,
                    body,
                });
                toast.success('تم إضافة نوع القرض');
            }

            await onRefresh?.();
            setShowPopup(false);
        } catch (err: any) {
            if (err.response?.data?.errors) {
                Object.entries(err.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                const msg =
                    err.response?.data?.msg || 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                setError(msg);
            }
        } finally {
            setLoading(false);
        }
    };

    const activeOptions = [
        { name: 'مفعّل', value: '1' },
        { name: 'غير مفعّل', value: '0' },
    ];

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span>{error}</span>
                                <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid grid-cols-2 gap-3">
                        {!isEdit && (
                            <TextInputForm
                                name="code"
                                label="رمز النوع (إنجليزي)"
                                placeholder="مثال: emergency_loan"
                                className="col-span-2"
                            />
                        )}
                        <TextInputForm name="loan_type" label="اسم القرض" placeholder="قرض شخصي" className="col-span-2" />
                        <TextInputForm name="max_amount" label="المبلغ الأقصى (ريال)" placeholder="100000" type="number" />
                        <TextInputForm name="return_amount" label="معدل العائد (%)" placeholder="2.5" type="number" />
                        <TextInputForm name="duration_in_months" label="الحد الأقصى للمدة (شهر)" placeholder="48" type="number" />
                        <TextInputForm name="sort_order" label="ترتيب العرض" placeholder="0" type="number" />
                        <SelectInputForm name="is_active" label="الحالة" options={activeOptions} placeholder="الحالة" />
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                        <SecondaryButton
                            onClick={() => setShowPopup(false)}
                            type="button"
                            className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                        >
                            إلغاء
                        </SecondaryButton>
                        <PrimaryButton type="submit" className="w-full text-base leading-5 tracking-normal font-medium py-[10px]">
                            {loading ? 'جاري الحفظ...' : isEdit ? 'حفظ التعديل' : 'إنشاء'}
                        </PrimaryButton>
                    </div>
                </form>
            </Form>
        </>
    );
}
