import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { cn } from '@/lib/utils';
import LoanTypeForm from './loanPage/LoanTypeForm';
import type { LoanTypeDto } from '@/features/selfServices/types/loanType.types';

interface Props {
    open: boolean;
    setShowPopup: (value: boolean) => void;
    editingLoanType: LoanTypeDto | null;
    onRefresh: () => void | Promise<void>;
}

export default function LoanTypePopup({ open, setShowPopup, editingLoanType, onRefresh }: Props) {
    const isEdit = Boolean(editingLoanType);

    return (
        <Dialog open={open}>
            <div
                className={cn('fixed inset-0', {
                    '!hidden': !open,
                })}
            />
            <DialogContent
                showCloseButton={false}
                className="max-w-[623px] rounded-lg p-8 bg-white-blue-50 font-cairo gap-0 [&_[aria-label=Close]]:opacity-0"
            >
                <DialogHeader className="flex flex-col items-center">
                    <div className="flex flex-row justify-between mb-4 w-full">
                        <div className="flex flex-row gap-2">
                            <PlusIcon />
                            <h3 className="text-[22px] font-bold text-primery-blue-500">
                                {isEdit ? 'تعديل نوع قرض' : 'إنشاء نوع قرض'}
                            </h3>
                        </div>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1] !mt-0"></div>
                </DialogHeader>
                <LoanTypeForm
                    editingLoanType={editingLoanType}
                    setShowPopup={setShowPopup}
                    onRefresh={onRefresh}
                />
            </DialogContent>
        </Dialog>
    );
}
